import { readFile } from "node:fs/promises";

import openapiTS, { astToString } from "openapi-typescript";

const schemaUrl = new URL("../../api/openapi.json", import.meta.url);
const typesUrl = new URL("../lib/api/types.ts", import.meta.url);
const generatedHeader = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

`;

const generated = generatedHeader + astToString(await openapiTS(schemaUrl));
const committed = await readFile(typesUrl, "utf8");

if (generated !== committed) {
  console.error("Frontend API types are stale. Run `pnpm gen:types` in apps/web.");
  process.exitCode = 1;
} else {
  console.log("Frontend API types match apps/api/openapi.json.");
}
